import React, { useState } from 'react';
import PropTypes from 'prop-types';

// core components
import Header from '../../components/header/header.jsx';
import HeaderBanner from '../../components/banner/banner.jsx';
import Footer from '../../components/footer/footer.jsx';

// sections for this page
import Buttons from './sections/buttons.jsx';
import ChatList from './sections/Chatlist.jsx';
import ChatRoom from './sections/ChatRoom.jsx';

const Components = () => {
    const [showChatPage, setShowChatPage] = useState(false);
    const [currentChat, setCurrentChat] = useState(null);

    const toggleChatPage = () => {
        setShowChatPage(!showChatPage);
    };

    const handleSelectChat = (chatId, otherUserId) => {
        setCurrentChat({ chatId, otherUserId });
        setShowChatPage(true);
    };

    return (
        <div id="main-wrapper">
            <Header />
            <div className="page-wrapper">
                <div className="container-fluid">
                    <HeaderBanner />
                    <Buttons />
                    {!showChatPage ? (
                        <button className="fixed-chat-button" onClick={toggleChatPage}>
                            채팅창 이동
                        </button>
                    ) : (
                        <ChatRoom
                            chatId={currentChat.chatId}
                            otherUserId={currentChat.otherUserId}
                            loginUserId={currentChat.otherUserId} // Update this line with correct login user id
                            goBack={() => setShowChatPage(false)}
                        />
                    )}
                    {!showChatPage && <ChatList onSelectChat={handleSelectChat} />} {/* 조건부 렌더링 */}
                </div>
            </div>
            <Footer />
        </div>
    );
};

Components.propTypes = {
    classes: PropTypes.object,
};

export default Components;
